from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for pnum in [6,7,8,17]:
    page=r.pages[pnum-1]
    print('PAGE',pnum)
    for i,img in enumerate(page.images):
        print(i,img.name, img.image.size)
        if pnum == 17:
            from pathlib import Path
            out=Path('tmp/pdfs') / f'roc-{i}-{img.name}'
            out.write_bytes(img.data)
            print('SAVED',out)
print('URL ANNOTATIONS')
for i,p in enumerate(r.pages,1):
    for ref in p.get('/Annots',[]):
        a=ref.get_object().get('/A',{})
        if a.get('/URI'): print(i,a.get('/URI'))
